async function submitStudentReview(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),status=form.querySelector(".review-form-status"),file=form.elements.photo.files?.[0];status.textContent="";status.classList.remove("error");if(file&&(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>4*1024*1024)){status.textContent="Choose a PNG, JPEG, or WebP photo up to 4 MB.";status.classList.add("error");return}button.disabled=true;button.textContent="Sending…";try{let image=null;if(file){const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error("The selected photo could not be read."));reader.readAsDataURL(file)});image={contentType:file.type,data:String(dataUrl).split(",")[1]}}const body={name:form.elements.name.value,college:form.elements.college.value,course:form.elements.course.value,rating:Number(form.elements.rating.value),review:form.elements.review.value,consent:form.elements.consent.checked,website:form.elements.website.value,image};const response=await fetch("/api/reviews",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||"Your review could not be submitted.");form.reset();previewReviewPhoto(form.elements.photo);status.textContent=result.message||"Thanks! Your review was submitted for approval."}catch(error){status.textContent=error.message||"Your review could not be submitted.";status.classList.add("error")}finally{button.disabled=false;button.textContent="Submit for approval"}}
